fn max_of_list(xs: List[Int]) -> Option[Int]
  requires true
  ensures len(xs) == 0 or result != None
  ensures len(xs) > 0 or result == None
  effects pure
  example max_of_list([3, 9, 1]) == Some(9)
  example max_of_list([]) == None
  example max_of_list([5]) == Some(5)
{
  match xs {
    [] => None
    [h, ..t] => 
      match max_of_list(t) {
        None => Some(h)
        Some(m) => Some(if h >= m then h else m)
      }
  }
}

fn remove_first_occurrence(xs: List[Int], value: Int) -> List[Int]
  requires true
  ensures len(result) == len(xs) - 1 or len(result) == len(xs)
  effects pure
  example remove_first_occurrence([3, 9, 1], 9) == [3, 1]
  example remove_first_occurrence([3, 9, 1], 10) == [3, 9, 1]
{
  match xs {
    [] => []
    [h, ..t] =>
      if h == value then t
      else [h] ++ remove_first_occurrence(t, value)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires true
  ensures len(xs) < 2 or result != None
  ensures not (len(xs) < 2) or result == None
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
  example second_largest([5, 2]) == Some(2)
{
  match xs {
    [] => None
    [h, ..t] =>
      match t {
        [] => None
        _ =>
          match max_of_list(xs) {
            None => None
            Some(max_val) => 
              max_of_list(remove_first_occurrence(xs, max_val))
          }
      }
  }
}

